    "guide_convimg_faq1_q": "\u06a9\u0648\u0646 \u0633\u0627 \u0641\u0627\u0631\u0645\u06cc\u0679 \u0645\u0646\u062a\u062e\u0628 \u06a9\u0631\u0648\u06ba\u061f",
