    "guide_convimg_faq2_a": "JPG \u0627\u0648\u0631 WebP \u0644\u0627\u0633\u06cc \u06c1\u06cc\u06ba \u2014 PNG \u0633\u06d2 \u062a\u0628\u062f\u06cc\u0644 \u06a9\u0631\u0646\u06d2 \u067e\u0631 \u062a\u06be\u0648\u0691\u06cc \u062a\u0641\u0635\u06cc\u0644 \u0636\u0627\u0626\u0639 \u06c1\u0648 \u0633\u06a9\u062a\u06cc \u06c1\u06d2\u06d4 PNG \u0622\u0624\u0679 \u067e\u0679 \u06c1\u0645\u06cc\u0634\u06c1 \u0644\u0627\u0633 \u0644\u06cc\u0633 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4",
    "guide_convimg_faq3_q": "\u06a9\u06cc\u0627 \u0645\u06cc\u06ba \u0645\u062a\u062d\u0631\u06a9 GIF \u062a\u0628\u062f\u06cc\u0644 \u06a9\u0631 \u0633\u06a9\u062a\u0627 \u06c1\u0648\u06ba\u061f",
