    "guide_convimg_faq4_q": "\u06a9\u06cc\u0627 \u0645\u06cc\u0631\u06cc \u062a\u0635\u0627\u0648\u06cc\u0631 \u06a9\u06c1\u06cc\u06ba \u0627\u067e \u0644\u0648\u0688 \u06c1\u0648\u062a\u06cc \u06c1\u06cc\u06ba\u061f",
    "guide_convimg_faq4_a": "\u0646\u06c1\u06cc\u06ba\u06d4 \u062a\u0628\u062f\u06cc\u0644\u06cc \u0645\u06a9\u0645\u0644 \u0637\u0648\u0631 \u067e\u0631 \u0622\u067e \u06a9\u06d2 \u0628\u0631\u0627\u0624\u0632\u0631 \u0645\u06cc\u06ba \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u061b \u0622\u067e \u06a9\u06d2 \u0622\u0644\u06d2 \u0633\u06d2 \u06a9\u0686\u06be \u0628\u0627\u06c1\u0631 \u0646\u06c1\u06cc\u06ba \u062c\u0627\u062a\u0627\u06d4",
