    "guide_case_rel2_t": "\u0648\u0631\u0688 \u06a9\u0627\u0624\u0646\u0679\u0631",
    "guide_case_rel2_d": "\u0628\u0631\u0627\u06c1 \u0631\u0627\u0633\u062a \u0644\u0641\u0638\u060c \u062d\u0631\u0641 \u0627\u0648\u0631 \u067e\u0691\u06be\u0646\u06d2 \u06a9\u06d2 \u0648\u0642\u062a \u06a9\u06d2 \u0627\u0639\u062f\u0627\u062f\u06d4",
    "guide_case_crumb_guides": "\u0631\u06c1\u0646\u0645\u0627\u0626\u06cc",
    "guide_case_crumb_cur": "\u0645\u062a\u0646 \u06a9\u0627 \u06a9\u06cc\u0633 \u06a9\u06cc\u0633\u06d2 \u0628\u062f\u0644\u06cc\u06ba",
    "guide_idx_crumb": "\u0631\u06c1\u0646\u0645\u0627\u0626\u06cc",
    "guide_idx_eyebrow": "\u0633\u06cc\u06a9\u06be\u06cc\u06ba",
    "guide_idx_h1": "\u0645\u0631\u062d\u0644\u06c1 \u0648\u0627\u0631 \u0631\u06c1\u0646\u0645\u0627\u0626\u06cc\u0627\u06ba",
    "guide_idx_intro": "\u06c1\u0631 DoKit \u0679\u0648\u0644 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0645\u062e\u062a\u0635\u0631 \u0627\u0648\u0631 \u0639\u0645\u0644\u06cc \u0645\u0631\u062d\u0644\u06c1 \u0648\u0627\u0631 \u0631\u06c1\u0646\u0645\u0627\u0626\u06cc\u06d4 \u0646\u06c1 \u0633\u0627\u0626\u0646 \u0627\u067e\u060c \u0646\u06c1 \u0645\u0634\u06a9\u0644 \u0627\u0644\u0641\u0627\u0638 \u2014 \u0635\u0631\u0641 \u0648\u06c1 \u0645\u0631\u0627\u062d\u0644 \u062c\u0648 \u0648\u0627\u0642\u0639\u06cc \u06a9\u0627\u0645 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u06c1\u0631 \u0631\u06c1\u0646\u0645\u0627\u0626\u06cc \u0627\u0646\u06af\u0631\u06cc\u0632\u06cc \u0627\u0648\u0631 \u0627\u0631\u062f\u0648 \u062f\u0648\u0646\u0648\u06ba \u0645\u06cc\u06ba \u062f\u0633\u062a\u06cc\u0627\u0628 \u06c1\u06d2\u06d4",
    "guide_idx_card1_t": "\u062a\u0635\u0648\u06cc\u0631\u0648\u06ba \u06a9\u0627 \u0633\u0627\u0626\u0632 \u06a9\u06cc\u0633\u06d2 \u0628\u062f\u0644\u06cc\u06ba",
    "guide_idx_card1_d": "\u067e\u06a9\u0633\u0644\u0632 \u06cc\u0627 \u0641\u06cc\u0635\u062f \u0645\u06cc\u06ba \u062a\u0635\u0648\u06cc\u0631 \u06a9\u06cc \u067e\u06cc\u0645\u0627\u0626\u0634 \u0628\u062f\u0644\u06cc\u06ba\u060c \u06a9\u0648\u0627\u0644\u0679\u06cc \u0628\u0631\u0642\u0631\u0627\u0631 \u0631\u06a9\u06be\u06cc\u06ba\u060c \u0627\u0648\u0631 \u0648\u06cc\u0628\u060c \u067e\u0631\u0646\u0679 \u06cc\u0627 \u062f\u0633\u062a\u0627\u0648\u06cc\u0632\u0627\u062a \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u06cc\u06a9\u0633\u067e\u0648\u0631\u0679 \u06a9\u0631\u06cc\u06ba\u06d4",
    "guide_idx_card1_b": "\u0627\u0645\u06cc\u062c \u0631\u06cc \u0633\u0627\u0626\u0632\u0631",
    "guide_idx_card2_t": "\u062a\u0635\u0648\u06cc\u0631\u0648\u06ba \u06a9\u0648 \u06a9\u0645\u067e\u0631\u06cc\u0633 \u06a9\u06cc\u0633\u06d2 \u06a9\u0631\u06cc\u06ba",
    "guide_idx_card2_d": "JPG\u060c PNG \u0627\u0648\u0631 WebP \u0641\u0627\u0626\u0644 \u0633\u0627\u0626\u0632 \u06a9\u0648\u0627\u0644\u0679\u06cc \u0645\u06cc\u06ba \u0648\u0627\u0636\u062d \u0641\u0631\u0642 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u06a9\u0645 \u06a9\u0631\u06cc\u06ba \u2014 \u0648\u06cc\u0628 \u0633\u0627\u0626\u0679\u0633 \u0627\u0648\u0631 \u0627\u06cc \u0645\u06cc\u0644 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0628\u06c1\u062a\u0631\u06cc\u0646\u06d4",
    "guide_idx_card2_b": "\u0627\u0645\u06cc\u062c \u06a9\u0645\u067e\u0631\u06cc\u0633\u0631",
    "guide_idx_card3_t": "\u062a\u0635\u0648\u06cc\u0631\u06cc \u0641\u0627\u0631\u0645\u06cc\u0679 \u06a9\u06cc\u0633\u06d2 \u062a\u0628\u062f\u06cc\u0644 \u06a9\u0631\u06cc\u06ba",
    "guide_idx_card3_d": "\u0633\u06cc\u06a9\u0646\u0688\u0648\u06ba \u0645\u06cc\u06ba JPG\u060c PNG \u0627\u0648\u0631 WebP \u06a9\u06d2 \u062f\u0631\u0645\u06cc\u0627\u0646 \u0628\u062f\u0644\u06cc\u06ba \u2014 \u0686\u06be\u0648\u0679\u06cc \u0641\u0627\u0626\u0644\u06cc\u06ba\u060c \u0648\u0633\u06cc\u0639 \u0645\u0637\u0627\u0628\u0642\u062a\u06d4",
    "guide_idx_card3_b": "\u0627\u0645\u06cc\u062c \u06a9\u0646\u0648\u0631\u0679\u0631",
    "guide_idx_card4_t": "\u0627\u0644\u0641\u0627\u0638 \u06a9\u06cc\u0633\u06d2 \u06af\u0646\u06cc\u06ba",
    "guide_idx_card4_d": "\u0645\u0636\u0627\u0645\u06cc\u0646\u060c \u0622\u0631\u0679\u06cc\u06a9\u0644\u0632 \u0627\u0648\u0631 \u06a9\u06cc\u067e\u0634\u0646\u0632 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0628\u0631\u0627\u06c1 \u0631\u0627\u0633\u062a \u0644\u0641\u0638 \u06af\u0646\u062a\u06cc\u060c \u067e\u0691\u06be\u0646\u06d2 \u06a9\u0627 \u0648\u0642\u062a \u0627\u0648\u0631 \u06a9\u0644\u06cc\u062f\u06cc \u0644\u0641\u0638 \u06a9\u06d2 \u0627\u0639\u062f\u0627\u062f \u062d\u0627\u0635\u0644 \u06a9\u0631\u06cc\u06ba\u06d4",
