    "guide_idx_card5_t": "\u0645\u062a\u0646 \u06a9\u0627 \u06a9\u06cc\u0633 \u06a9\u06cc\u0633\u06d2 \u0628\u062f\u0644\u06cc\u06ba",
    "guide_idx_card5_d": "ALL-CAPS \u0633\u0631\u062e\u06cc\u0627\u06ba \u062f\u0631\u0633\u062a \u06a9\u0631\u06cc\u06ba \u0627\u0648\u0631 \u0639\u0646\u0648\u0627\u0646\u0627\u062a \u0641\u0627\u0631\u0645\u06cc\u0679 \u06a9\u0631\u06cc\u06ba \u2014 \u0686\u06be \u06a9\u06cc\u0633 \u0627\u0633\u0679\u0627\u0626\u0644\u060c \u06c1\u0631 \u0627\u06cc\u06a9 \u0635\u0631\u0641 \u0627\u06cc\u06a9 \u06a9\u0644\u06a9 \u067e\u0631\u06d4",
